// ===========================================================================
//  Lesson 17 — a 35.7 MHz clock, generated by:
//
//    ecppll -n pll36 -i 25 -o 36 -f pll36.v
//
//  WHY NOT LESSON 16'S 40 MHz PLL. Because this core does not close timing at
//  40. Adding the privileged architecture, the timer and the M extension cost
//  about six megahertz, and three placer seeds put the maximum at 41.1 / 40.1
//  / 39.6 -- one of three below the target. A design that passes on two seeds
//  in three has not met timing; it has got away with it twice.
//
//  So: 35.7 MHz, which is the nearest the PLL can make to the 36 asked for,
//  and about 11% below the slowest measured placement. Lesson 16 ships 40
//  against a worst case of 45.7, which is 14%. The margins are deliberate and
//  the same kind.
//
//  ecppll works in ratios of the 25 MHz input through a VCO, so 36.000 is not
//  available and 35.7143 is. The UART divisor is computed from CLK_HZ, so
//  nothing downstream cares -- which is the third time in this course that
//  making the clock a parameter has paid for itself.
//
//  As in lesson 04: EHXPLLL is a hard analogue block with no simulation model,
//  so this file is in SRCS and not in SIM_SRCS, and `locked` holds the design
//  in reset until the PLL has actually locked.
// ===========================================================================
// diamond 3.7 accepts this PLL
// diamond 3.8-3.9 is untested
// diamond 3.10 or higher is likely to abort with error about unable to use feedback signal
// cause of this could be from wrong CPHASE/FPHASE parameters
module pll36
(
    input clkin, // 25 MHz, 0 deg
    output clkout0, // 35.7143 MHz, 0 deg
    output locked
);
(* FREQUENCY_PIN_CLKI="25" *)
(* FREQUENCY_PIN_CLKOP="35.7143" *)
(* ICP_CURRENT="12" *) (* LPF_RESISTOR="8" *) (* MFG_ENABLE_FILTEROPAMP="1" *) (* MFG_GMCREF_SEL="2" *)
EHXPLLL #(
        .PLLRST_ENA("DISABLED"),
        .INTFB_WAKE("DISABLED"),
        .STDBY_ENABLE("DISABLED"),
        .DPHASE_SOURCE("DISABLED"),
        .OUTDIVIDER_MUXA("DIVA"),
        .OUTDIVIDER_MUXB("DIVB"),
        .OUTDIVIDER_MUXC("DIVC"),
        .OUTDIVIDER_MUXD("DIVD"),
        .CLKI_DIV(7),
        .CLKOP_ENABLE("ENABLED"),
        .CLKOP_DIV(17),
        .CLKOP_CPHASE(8),
        .CLKOP_FPHASE(0),
        .FEEDBK_PATH("CLKOP"),
        .CLKFB_DIV(10)
    ) pll_i (
        .RST(1'b0),
        .STDBY(1'b0),
        .CLKI(clkin),
        .CLKOP(clkout0),
        .CLKOS(),
        .CLKOS2(),
        .CLKOS3(),
        .CLKFB(clkout0),
        .CLKINTFB(),
        .PHASESEL0(1'b0),
        .PHASESEL1(1'b0),
        .PHASEDIR(1'b1),
        .PHASESTEP(1'b1),
        .PHASELOADREG(1'b1),
        .PLLWAKESYNC(1'b0),
        .ENCLKOP(1'b0),
        .LOCK(locked),
        .ENCLKOS(),
        .ENCLKOS2(),
        .ENCLKOS3(),
        .INTLOCK(),
        .REFCLK()
	);
endmodule
